import { t, type BookPage, type Chapter, type PageKind } from './types';
import { letters } from './letters';
import { reasons, reasonsAfterword } from './reasons';
import { envelopes } from './envelopes';

export const chapters: Chapter[] = [
  [1, 6, 'Untuk Aira', 'For Aira', 'Buka pelan-pelan, ya.', 'Take your time opening this.'],
  [7, 16, 'Awal yang tak disangka', 'An unexpected beginning', 'Dari Litmatch, jadi kita.', 'From Litmatch to us.'],
  [17, 24, 'Malam, pukul 10:29', 'The night, at 10:29', 'Satu waktu yang kita simpan.', 'A time we are keeping.'],
  [25, 36, 'Sepuluh hari pertama', 'The first ten days', 'Nggak langsung mulus.', 'Not instantly smooth.'],
  [37, 46, 'Pelan-pelan, kita', 'Little by little, us', 'Belajar saling memahami.', 'Learning each other.'],
  [47, 54, 'Suara & satu kenangan', 'A voice & a memory', 'Panggilan pertama, dan yang khusus.', 'Our first call, and something special.'],
  [55, 64, 'Bahasa kita', 'Our little language', 'Tidak tersedia di kamus.', 'Not found in any dictionary.'],
  [65, 76, 'Aira, segala versinya', 'Every version of Aira', 'Termasuk yang lagi bad mood.', 'Including the moody version.'],
  [77, 86, 'Hal-hal kecil', 'The little things', 'Yang ternyata berarti.', 'Things that turn out to matter.'],
  [87, 122, 'Dua belas surat', 'Twelve letters', 'Dari aku, tanpa buru-buru.', 'From me, without rushing.'],
  [123, 147, 'Lima puluh alasan', 'Fifty little reasons', 'Bukan daftar syarat. Cuma kamu.', 'Not a checklist. Just you.'],
  [148, 156, 'Main sebentar?', 'Shall we play?', 'Sembilan permainan untukmu.', 'Nine games, just for you.'],
  [157, 166, 'Buka kalau...', 'Open when...', 'Sepuluh amplop, sepuluh suasana.', 'Ten envelopes, ten kinds of day.'],
  [167, 174, 'Nanti, kalau ketemu', 'When we finally meet', 'Harapan, bukan tanggal yang dipaksa.', 'A hope, not a forced deadline.'],
  [175, 180, 'Jejak kecil kita', 'Our little timeline', 'Yang sudah terjadi, yang diharapkan.', 'What happened, what we hope for.'],
  [181, 190, 'Di sela halaman', 'Between the pages', 'Catatan yang agak tersembunyi.', 'Some slightly hidden notes.'],
  [191, 194, 'Sekarang giliranmu', 'Now it is your turn', 'Aku juga mau dengar suaramu.', 'I want your voice here too.'],
  [195, 200, 'Bukan akhir ceritanya', 'Not the end of our story', 'Ada satu hal lagi, Bebyycuu.', 'One more thing, Bebyycuu.'],
].map(([start, end, id, en, sid, sen]) => ({ start: Number(start), end: Number(end), title: t(String(id), String(en)), subtitle: t(String(sid), String(sen)) }));

export const pages: BookPage[] = [];
function p(id: string, en: string, bodyId: string, bodyEn: string, kind: PageKind = 'story') {
  const number = pages.length + 1;
  const chapter = chapters.findIndex(c => number >= c.start && number <= c.end);
  const page: BookPage = { number, id: `page-${String(number).padStart(3, '0')}`, chapter, kind, title: t(id, en), body: t(bodyId, bodyEn) };
  pages.push(page);
  return page;
}

// 1-6: a quiet dedication, before the story begins.
p('Untuk kamu, Aira.', 'For you, Aira.', 'Buku kecil ini punya satu pembaca favorit. Kamu.\n\nSelamat empat bulan, Bebyycuu.\nDari Shivam, yang ternyata bisa cerewet sampai dua ratus halaman.', 'This little book has one favourite reader. You.\n\nHappy four months, Bebyycuu.\nFrom Shivam, who apparently can talk for two hundred pages.', 'dedication');
p('Sini, duduk sebentar.', 'Come, stay a while.', 'Nggak perlu dibaca sekaligus. Kalau kamu lagi malas, kita anggap satu halaman sudah kemajuan. Aku bikin ini supaya bisa kamu buka lagi, bukan supaya selesai secepat mungkin.', 'You do not have to read it all at once. If you are feeling lazy, one page counts as progress. I made this for you to come back to, not to finish as quickly as possible.');
p('Sedikit petunjuk dari penulis.', 'A small note from the writer.', 'Balik halaman lewat tombol, geser, atau panah keyboard. Ketuk foto untuk melihat lebih dekat. Beberapa hati menyimpan pesan. Dan kalau kamu lupa berhenti di mana, tenang. Bukunya ingat.', 'Turn pages with the buttons, a swipe, or your keyboard arrows. Tap a photo for a closer look. Some hearts hold notes. And if you forget where you stopped, relax. The book remembers.');
p('Bukan kita yang dirapikan.', 'Not a polished version of us.', 'Ada yang manis, ada yang konyol, ada awal yang agak ribut. Aku ingin semuanya dapat tempat. Kalau isinya terlalu sempurna, nanti kamu malah tanya, ini pasangan siapa?', 'There is sweetness, silliness, and a slightly noisy beginning. I want all of it to have room. If everything were too perfect, you might wonder whose relationship this is.');
p('Kamu nggak harus menangis.', 'You do not have to cry.', 'Serius. Hadiah ini nggak punya syarat reaksi. Senyum boleh, komentar boleh, menggoda penulis juga boleh. Cuma jangan pakai buku ini sebagai bukti bahwa aku kebanyakan waktu luang.', 'Seriously. This gift does not demand a reaction. You can smile, comment, or tease the writer. Just do not use it as evidence that I have too much free time.', 'note');
p('Satu tempat yang khusus.', 'A place just for you.', 'Aku menaruh namamu di sampul karena memang kamu yang kupikirkan saat membuatnya. Bukan nama yang bisa diganti begitu saja. Aira. Pas di sini.', 'I put your name on the cover because you are who I had in mind while making it. Not a name that can simply be swapped. Aira. Exactly right here.');

// 7-16: the beginning, without invented dialogue.
p('Awalnya, dua orang asing.', 'At first, two strangers.', 'Sebelum semua panggilan panjang itu, kita cuma dua orang yang belum saling kenal. Aku suka mengingat titik itu. Belum ada kita, lalu pelan-pelan ada.', 'Before all the long nicknames, we were two people who did not know each other. I like remembering that point. There was no us yet, and then, gradually, there was.', 'quote');
p('Litmatch.', 'Litmatch.', 'Itu tempat kita bertemu. Nggak perlu kuberi nama tempat yang lebih romantis supaya ceritanya terasa penting. Awal dari aplikasi juga bisa jadi awal sesuatu yang sungguhan.', 'That is where we met. I do not need a more romantic place to make the story matter. Something real can begin on an app too.');
p('Dari banyak kemungkinan.', 'Of all the possibilities.', 'Lucu ya, perkenalan bisa lewat begitu saja. Tapi yang ini malah sampai punya sampul, halaman, dan penulis yang agak niat. Aku senang orang di cerita itu kamu.', 'Funny how an introduction can just pass by. This one ended up with a cover, pages, and a rather dedicated writer. I am glad the person in the story is you.');
p('Bukan profil lagi.', 'More than a profile.', 'Kamu bukan cuma nama yang pernah muncul di layar. Kamu orang yang ingin kukenal lebih jauh. Bedanya sederhana di kalimat, tapi lumayan besar waktu dirasakan.', 'You are not just a name that once appeared on a screen. You are someone I want to know better. A simple difference to write, a rather big one to feel.');
p('Lanjut ke WhatsApp.', 'Then, WhatsApp.', 'Malam yang sama, kita pindah ke WhatsApp. Kalau ditulis begini cuma satu kalimat. Padahal buat cerita kita, itu pintu berikutnya.', 'That same night, we moved to WhatsApp. Written down, it is just one sentence. For our story, it was the next door.');
p('Dua aplikasi, satu awal.', 'Two apps, one beginning.', 'Litmatch tempat berkenalan. WhatsApp tempat kita melanjutkan malam itu. Aku menyimpan keduanya, karena cerita ini memang mulai dari hal sesederhana itu.', 'Litmatch is where we met. WhatsApp is where we continued that night. I am keeping both, because the story really did begin that simply.');
p('Dulu belum kenal kamu.', 'I did not know you then.', 'Sekarang aku bisa menulis Bebyycuu dan langsung tahu orang yang kumaksud. Padahal sebelum perkenalan itu, aku bahkan belum mengenal Aira. Perubahan kecil yang ternyata nggak kecil.', 'Now I can write Bebyycuu and immediately know who I mean. Before that introduction, I did not even know Aira. A little change that turned out not to be little at all.');
p('Boleh biasa saja.', 'It can be ordinary.', 'Awal kita nggak harus terdengar seperti film. Kadang justru kalimat kita ketemu di Litmatch terasa paling kita. Sederhana, sedikit random, lalu ternyata berlanjut.', 'Our beginning does not need to sound like a film. Sometimes we met on Litmatch is the most us sentence there is. Simple, a little random, and then it continued.');
p('Kalau dari sisi kamu?', 'What about your side?', 'Bagian apa dari awal kita yang paling kamu ingat? Aku penasaran dengan versimu. Nggak harus sama dengan yang kupikirkan.', 'What do you remember most about our beginning? I am curious about your version. It does not need to match what I think.', 'question');
p('Ternyata kamu.', 'It turned out to be you.', 'Orang yang dulu belum kukenal, sekarang punya banyak panggilan dariku. Perjalanannya nggak perlu kubuat lebih megah. Aku suka hasil akhirnya sejauh ini: kita.', 'Someone I did not know now has so many nicknames from me. I do not need to make the journey sound grander. I like where it has brought us so far: us.', 'quote');

// 17-24: the exact beginning of the relationship.
p('6 Juli 2026.', '6 July 2026.', 'Ini tanggal hubungan kita dimulai. Aku tulis besar-besar, untuk kenangan. Dan sedikit untuk berjaga-jaga kalau Bebyycuu lupa.', 'This is the date our relationship began. I am writing it nice and big for the memory. And as a small precaution in case Bebyycuu forgets.', 'quote');
p('10:29 PM.', '10:29 PM.', 'Jam sepuluh lewat dua puluh sembilan malam. Spesifik sekali, ya? Sekarang kalau melihat angka itu, aku punya satu alasan kecil untuk memikirkan kita.', 'Twenty-nine minutes past ten at night. Very specific, right? Now seeing that time gives me one small reason to think of us.', 'quote');
p('Satu menit punya nama.', 'A minute with our names.', 'Sebagian besar waktu lewat tanpa diberi judul. Menit ini beda. Di bukuku, 10:29 punya catatan kecil: di sini kita mulai.', 'Most minutes pass without a title. This one is different. In my book, 10:29 has a small note: this is where we began.');
p('Bukan tanggal acak.', 'Not a random date.', 'Aku bisa menulis tanggal ini dengan tenang karena memang ini yang kita punya. Nggak perlu mengganti dengan tanggal yang terlihat lebih cantik. Yang membuatnya khusus bukan bentuk angkanya.', 'I can write this date with confidence because it is ours. No need to choose a prettier-looking one. The shape of the numbers is not what makes it special.');
p('Untuk yang suka lupa.', 'For the forgetful one.', 'Catatan resmi untuk Aira: kalau lupa tanggal kita, buka halaman tujuh belas. Kalau lupa jamnya, halaman delapan belas. Kalau lupa siapa penulisnya, nah itu baru keterlaluan, Bebyycuu.', 'An official note for Aira: if you forget our date, open page seventeen. The time is on page eighteen. If you forget who wrote the book, well, that is going a little far, Bebyycuu.', 'note');
p('Dua hal yang kusimpan.', 'Two things I am keeping.', 'Tanggalnya, karena di sana kita mulai. Kamu, dalam arti perhatian yang ingin kuberikan, bukan sesuatu yang bisa kumiliki seenaknya. Ada bedanya, dan aku ingin mengingat itu.', 'The date, because that is where we began. You, in the sense of care I want to give, not someone I get to possess. There is a difference, and I want to remember it.');
p('Empat bulan kemudian.', 'Four months later.', 'Kita punya buku ini. Bukan karena empat bulan harus dirayakan dengan sesuatu yang besar, tapi karena aku ingin membuat sesuatu yang khusus. Ternyata agak banyak halamannya.', 'We have this book. Not because four months demands something big, but because I wanted to make something specific for you. It turned out to have quite a few pages.');
p('Simpan waktu, bukan buru-buru.', 'Keep the time, do not rush it.', 'Aku suka tahu kapan cerita ini dimulai. Tapi setelahnya, kita nggak perlu mengejar kalender orang lain. Kedekatan kita boleh tumbuh dengan cara yang masuk akal buat kita.', 'I like knowing when the story began. After that, we do not have to chase someone else\'s calendar. Our closeness can grow in a way that makes sense for us.');

// 25-36: honest reflections on the approximately ten difficult days.
p('Nggak langsung mulus.', 'Not instantly smooth.', 'Sekitar sepuluh hari pertama kita berisi salah paham dan ribut kecil. Bagian ini tetap masuk buku. Aku nggak mau menghapusnya cuma supaya semuanya terlihat manis.', 'Our first ten days or so included misunderstandings and little fights. This part stays in the book. I do not want to erase it just to make everything look sweet.');
p('Kita masih belajar.', 'We were still learning.', 'Dua orang baru dekat belum tentu langsung tahu cara membaca maksud satu sama lain. Aku juga perlu belajar, bukan cuma menunggu kamu mengerti aku.', 'Two people growing close do not automatically know how to read each other. I needed to learn too, not just wait for you to understand me.');
p('Bukan lomba paling benar.', 'Not a contest of being right.', 'Kalau tujuannya cuma menang, kita bisa kehilangan alasan kenapa mau bicara. Aku lebih ingin ada pengertian daripada satu orang merasa kalah.', 'If the only aim is to win, we can lose the reason for talking. I would rather have understanding than one person feeling defeated.', 'quote');
p('Bagian yang kurang rapi.', 'The untidy part.', 'Aku bisa mengingat awal itu tanpa menjadikannya daftar kesalahan. Ini cerita dua orang yang belum menemukan cara paling pas untuk dekat. Bukan berkas untuk saling menyalahkan.', 'I can remember that beginning without making a list of faults. This is about two people who had not found their best way of being close yet. Not a file for blaming each other.');
p('Menebak bukan tahu.', 'Guessing is not knowing.', 'Kadang kepala keburu mengisi bagian yang kosong. Padahal satu pertanyaan bisa lebih adil daripada satu kesimpulan. Catatan ini terutama buat aku sendiri.', 'Sometimes the mind fills in a gap too quickly. One question can be fairer than one conclusion. This note is especially for me.');
p('Kalimat yang butuh ruang.', 'Words that need room.', 'Tidak semua yang penting langsung keluar dengan rapi. Kalau kamu belum bisa menjelaskan, aku ingin ingat bahwa bingung juga boleh punya tempat.', 'Not everything important comes out neatly at once. If you cannot explain yet, I want to remember that confusion deserves room too.');
p('Kamu paling ingin dipahami soal apa?', 'What do you most want understood?', 'Ada bagian dari dirimu yang sering salah ditangkap orang? Kalau mau, tulis di sini. Nggak ada jawaban yang harus terdengar manis.', 'Is there a part of you people often misread? Write it here if you want. Your answer does not have to sound sweet.', 'question');
p('Nggak ada piala ribut.', 'No trophy for fighting.', 'Aku nggak menganggap ribut membuat hubungan otomatis lebih hebat. Yang ingin kuhargai adalah usaha mengenal setelahnya, bukan rasa capeknya.', 'I do not think arguments automatically make a relationship greater. What I want to appreciate is learning about each other afterwards, not the exhaustion.');
p('Boleh ambil jeda.', 'A pause is allowed.', 'Jeda nggak harus berarti nggak peduli. Kadang orang cuma butuh waktu supaya yang keluar bukan semua kata yang nanti disesali.', 'A pause does not have to mean not caring. Sometimes someone needs time so the words that come out are not all the ones they will regret.');
p('Aku juga bisa keliru.', 'I can get it wrong too.', 'Menjadi orang yang menulis buku ini tidak membuatku jadi yang paling paham hubungan kita. Kamu boleh membetulkan. Bahkan kalau tata letaknya sudah cantik.', 'Being the person writing this book does not make me the expert on us. You can correct me. Even if the layout is already pretty.', 'note');
p('Yang nggak ingin kubawa.', 'What I do not want to carry.', 'Aku nggak ingin membawa catatan siapa paling banyak salah. Kalau ada yang perlu dibicarakan, kita bisa membicarakan halnya. Nggak harus menjadikan orangnya buruk.', 'I do not want to carry a tally of who made more mistakes. If something needs discussing, we can discuss the issue without turning the person into the problem.');
p('Lalu kita lebih dekat.', 'Then we grew closer.', 'Sesudah awal yang agak ribut, kita pelan-pelan saling memahami. Aku suka bagian pelan-pelannya. Kedekatan itu terasa tumbuh, bukan muncul karena satu kalimat ajaib.', 'After that noisy beginning, we gradually understood each other better. I like the gradual part. Our closeness grew; it did not appear because of one magical sentence.');

// 37-46: getting closer, without claiming unprovided events.
p('Pelan-pelan itu tetap maju.', 'Slowly is still forward.', 'Kita nggak langsung tahu semua hal. Tapi dari sedikit lebih mengerti, ada sedikit lebih dekat. Aku senang proses seperti itu juga dapat halaman.', 'We did not know everything at once. But from a little more understanding came a little more closeness. I am glad that process gets a page too.', 'quote');
p('Bukan membaca pikiran.', 'Not mind reading.', 'Aku ingin mengenal kamu, bukan merasa harus bisa menebak kamu terus. Kalau ada yang belum kuketahui, pertanyaan masih jauh lebih berguna daripada sok paham.', 'I want to know you, not feel I must constantly guess you. When there is something I do not know, a question is more useful than pretending I understand.');
p('Yang beda boleh tetap beda.', 'Different can stay different.', 'Kita bisa punya reaksi berbeda terhadap sesuatu. Itu nggak otomatis membuat salah satu perasaannya tidak sah. Dekat bukan berarti jadi salinan.', 'We can react differently to something. That does not automatically make either feeling invalid. Being close does not mean becoming copies.');
p('Ada ruang untuk kamu.', 'There is room for you.', 'Buku ini banyak memakai suaraku. Tapi aku ingin kamu tahu, aku tertarik dengan versi ceritamu juga. Kamu bukan cuma tokoh yang terus kutuliskan.', 'This book uses my voice a lot. But I want you to know I care about your version too. You are not just a character I keep writing about.');
p('Mau didengar atau dibantu?', 'Listening or helping?', 'Kadang dua kebutuhan itu beda. Aku ingin lebih pandai menanyakannya, daripada langsung memberi jawaban panjang saat kamu cuma ingin cerita.', 'Sometimes those needs are different. I want to get better at asking, rather than offering a long answer when you just want to talk.');
p('Tidak harus selesai hari ini.', 'Not everything needs finishing today.', 'Ada percakapan yang perlu waktu. Aku ingin bisa menghargai prosesnya tanpa memaksa akhir yang cepat cuma supaya aku merasa lega.', 'Some conversations need time. I want to respect that process without forcing a quick ending just so I feel relieved.');
p('Dekat, bukan hafal.', 'Close, not memorised.', 'Kamu boleh berubah pikiran, belajar hal baru, dan punya cara menjelaskan yang berbeda. Aku nggak ingin mengenal satu versi kamu lalu mengunci pintunya.', 'You can change your mind, learn something new, and explain yourself differently. I do not want to know one version of you and then lock the door.');
p('Apa yang ingin kamu ceritakan?', 'What would you like to tell me?', 'Bukan pertanyaan ujian. Boleh sesuatu yang kecil, random, atau yang belum sempat kamu jelaskan. Aku ingin ada tempat untuk itu.', 'Not an exam question. It can be something small, random, or something you have not had room to explain. I want a place for that.', 'question');
p('Satu pengingat kecil.', 'A little reminder.', 'Kalau merasa sudah sangat mengenalmu, aku perlu tetap mendengarkan. Terlalu yakin kadang justru membuat orang berhenti memperhatikan.', 'When I feel I know you very well, I still need to listen. Being too certain can make a person stop paying attention.', 'note');
p('Masih ingin tahu.', 'Still curious.', 'Empat bulan bukan titik berhenti mengenal. Aku masih penasaran pada cara kamu melihat banyak hal. Penasaran yang ramah, bukan yang menginterogasi.', 'Four months is not the end of getting to know you. I am still curious about how you see things. Friendly curiosity, not an interrogation.');

// 47-54: supplied memories, with no invented dates or dialogue.
p('Pertama kali menelepon.', 'The first time we called.', 'Panggilan pertama kita itu berkesan. Aku sengaja memberi tempat sendiri di buku ini. Beberapa momen memang tidak perlu ramai untuk jadi penting.', 'Our first call was memorable. I deliberately gave it its own place in the book. Some moments do not need a crowd to matter.');
p('Bukan cuma tulisan.', 'More than written words.', 'Ada bedanya membaca seseorang dan mendengarnya. Orang yang tadinya kukenal lewat tulisan ternyata bisa terasa lebih dekat dengan cara lain juga. Panggilan pertama itu salah satu langkahnya.', 'There is a difference between reading someone and hearing them. Someone I first knew through writing could feel closer in another way too. That first call was one of those steps.');
p('Ruang kecil buat kenangan.', 'A little space for a memory.', 'Dari banyak bagian awal kita, panggilan pertama itu masih ingin kuberi ruang khusus. Ada langkah yang kelihatan sederhana, tapi beda saat orangnya kamu.', 'Among the parts of our beginning, I still want to give that first call a special space. Some steps look simple, but feel different when the person is you.');
p('Kalau kamu ingat satu bagian...', 'If you remember one part...', 'Apa yang paling terasa dari panggilan pertama itu buatmu? Boleh tulis dengan bahasamu sendiri. Nggak harus panjang.', 'What stands out most about our first call for you? You can write it in your own words. It does not have to be long.', 'question');
p('Iya, momen cium itu.', 'Yes, that kiss moment.', 'Aku nggak akan pura-pura bagian ini nggak ada. Ada momen cium yang khusus di awal kedekatan kita. Yang itu. Cukup judulnya saja, kamu juga tahu.', 'I will not pretend this part is not here. There was a special kiss moment in our early connection. That one. The title is enough; you know.', 'quote');
p('Yang boleh tetap pribadi.', 'What can stay private.', 'Tidak semua kenangan perlu dijelaskan sampai detail terakhir. Ada yang bisa kusimpan dengan perhatian, tanpa membuatnya jadi cerita untuk orang lain.', 'Not every memory needs its last detail explained. Some can be kept with care without turning them into a story for everyone else.');
p('Jangan senyum sendiri.', 'Do not smile to yourself.', 'Oke, sebenarnya boleh. Aku juga sedang menulis bagian ini sambil tahu betul kenapa halaman sebelumnya punya tempat sendiri. Lanjut dulu, Cantikkcuu.', 'Okay, you can. I am writing this knowing exactly why that earlier page has its own place. Carry on, Cantikkcuu.', 'note');
p('Dua kenangan, nggak perlu dibandingkan.', 'Two memories, no comparison needed.', 'Panggilan pertama dan momen cium itu punya rasa masing-masing. Aku nggak perlu memilih mana yang paling berarti. Keduanya boleh ada di sini.', 'The first call and that kiss moment each have their own feeling. I do not need to choose which means more. Both can be here.');

// 55-64: the real nickname dictionary.
p('Kamus kecil kita.', 'Our little dictionary.', 'Bahasa resmi mungkin tidak siap. Aku juga tidak sepenuhnya siap melihat semuanya dicetak rapi. Tapi baiklah, demi dokumentasi.', 'Official language may not be ready. I am not fully ready to see all of it neatly printed either. But fine, for documentation.', 'quote');
p('Bebyycuu.', 'Bebyycuu.', 'Versi dariku untukmu. Huruf tambahannya memang ada. Jangan dipotong, nanti rasanya seperti lagi disuruh cepat selesai.', 'My version for you. The extra letters are deliberate. Do not cut them short; it might sound like we are rushing.');
p('Cantikkcuu.', 'Cantikkcuu.', 'Aku nggak sedang menulis penilaian penampilan. Ini caraku memanggil kamu dengan sayang. Kamu boleh menerimanya bahkan saat sedang tidak merasa cantik.', 'I am not writing an appearance rating. This is my affectionate name for you. You can accept it even when you do not feel pretty.');
p('Duniyakuu.', 'Duniyakuu.', 'Salah satu namamu di bahasa kita. Manis, iya. Tapi bukan berarti hidupmu harus berputar hanya di aku. Kamu tetap punya dirimu sendiri.', 'One of your names in our language. Sweet, yes. But it does not mean your life must revolve around me. You still belong to yourself.');
p('Darlingcuuu.', 'Darlingcuuu.', 'Ada bahasa Inggrisnya, ada tambahan kita sendiri. Sangat tidak efisien secara ejaan. Sangat cocok dipakai untuk kamu.', 'A little English, a little of our own addition. Very inefficient spelling. Very appropriate for you.');
p('Istriicuuuu.', 'Istriicuuuu.', 'Panggilan sayang kita, bukan dokumen resmi. Aku menikmati manisnya tanpa memakai itu untuk memaksa masa depan. Santai dulu, bu editor kalender.', 'Our affectionate nickname, not an official document. I enjoy its sweetness without using it to force the future. Easy there, calendar editor.');
p('Dari Aira untuk Shivam.', 'From Aira to Shivam.', 'Bebyycu. Ciyanggcuu. Dan... Gay. Peralihan suasananya memang lumayan mendadak. Aku suka bahwa kamus kita tidak berusaha terlihat berwibawa.', 'Bebyycu. Ciyanggcuu. And... Gay. Quite a sudden change in mood. I like that our dictionary is not trying to look dignified.');
p('Bagian balasan.', 'The replies section.', 'Lesbian. Bebyycuu. Ciyanggcuu. Tiga balasan dariku, tergantung mode. Tolong jangan berharap buku ini konsisten anggun setelah halaman ini.', 'Lesbian. Bebyycuu. Ciyanggcuu. Three of my replies, depending on the mode. Please do not expect consistent elegance from this book after this page.');
p('Pilih panggilan hari ini.', 'Choose today\'s nickname.', 'Kalau sekarang aku cuma boleh memanggil kamu dengan satu nama, kamu mau yang mana? Tulis pilihanmu. Panjang hurufnya bebas, asal masih muat.', 'If I could call you just one name right now, which would you choose? Write your pick. As many extra letters as you like, as long as it fits.', 'question');
p('Tidak perlu dimengerti semua orang.', 'Not everyone needs to understand.', 'Ada kata yang lucu karena kita yang memakainya. Kalau orang lain bingung, biarkan. Ini memang kamus untuk dua pembaca.', 'Some words are funny because we use them. If someone else is confused, let them be. This is a dictionary for two readers.', 'quote');

// 65-76: affectionate observations, never invented habits.
p('Aira, bukan versi iklan.', 'Aira, not the advert version.', 'Kamu nggak harus selalu ceria, rajin, dan ingat semua hal supaya cocok jadi orang di buku ini. Justru aku ingin kamu mengenali dirimu di sini.', 'You do not have to be cheerful, productive, and remember everything to belong in this book. I want you to recognise yourself here.');
p('Kalau sedang bad mood.', 'When you are in a bad mood.', 'Aku boleh menggoda sedikit, tapi perasaanmu bukan leluconnya. Kalau lagi benar-benar kesal, aku ingin tahu kapan harus berhenti bercanda.', 'I can tease a little, but your feelings are not the joke. When you are genuinely upset, I want to know when to stop joking.');
p('Departemen rebahan.', 'The lying-down department.', 'Kalau rasa malas punya jabatan, mungkin kamu sudah dipanggil untuk wawancara. Tapi hari ini boleh istirahat. Tidak semua jam harus menghasilkan sesuatu.', 'If laziness had a job opening, you might get an interview. But today you can rest. Not every hour has to produce something.', 'note');
p('Tunggu, lupa apa tadi?', 'Wait, what did we forget?', 'Tenang, Bebyycuu. Buku ini ingat halaman terakhir buat kamu. Aku tidak sedang menghakimi. Aku cuma menambahkan fitur yang sangat memahami pembacanya.', 'Relax, Bebyycuu. The book remembers your last page. I am not judging. I just added a feature that understands its reader very well.');
p('Capek bukan selalu malas.', 'Tired is not always lazy.', 'Aku ingin tetap membedakan keduanya. Kadang godaan yang ringan harus memberi jalan untuk istirahat yang memang dibutuhkan.', 'I want to keep telling the difference. Sometimes a light tease needs to make way for genuinely needed rest.');
p('Tidak wajib dalam mood baik.', 'No good-mood requirement.', 'Kamu boleh membuka hadiah ini dengan hari yang biasa saja, bahkan yang kurang enak. Halaman manisnya tidak dibatalkan karena suasana hatimu.', 'You can open this gift on an ordinary day, even a rough one. The sweet pages are not cancelled because of your mood.');
p('Yang bikin nyaman itu apa?', 'What feels comforting?', 'Kalau sedang bad mood, kamu paling ingin diapakan? Didengar, diberi ruang, atau hal lain? Aku lebih suka tahu daripada menebak.', 'When you are in a bad mood, what do you most want? Listening, space, or something else? I would rather know than guess.', 'question');
p('Pengumuman penting.', 'An important announcement.', 'Aira sedang malas bukan berarti Aira rusak. Mohon tidak mencoba memulai ulang manusia. Sediakan waktu istirahat secukupnya.', 'Aira being lazy does not mean Aira is broken. Please do not try restarting the human. Allow a reasonable amount of rest.', 'note');
p('Lupa tidak sama dengan tak peduli.', 'Forgetting is not the same as not caring.', 'Aku ingin ingat itu juga. Ironis ya, surat tentang lupa malah berisi pengingat untukku. Ya sudah, kita sama-sama manusia.', 'I want to remember that too. Ironic, a page about forgetting contains a reminder for me. Fine, we are both human.');
p('Banyak sisi, satu Aira.', 'Many sides, one Aira.', 'Yang manis, yang kesal, yang malas, yang lupa. Semuanya bukan halaman terpisah yang harus kamu pilih satu untuk diperlihatkan.', 'The sweet side, the upset side, the lazy side, the forgetful side. They are not separate pages from which you must choose just one to show.');
p('Candaan boleh dibetulkan.', 'Jokes can be corrected.', 'Kalau ada godaan yang nggak terasa enak, kamu boleh bilang. Aku nggak mau lebih sayang pada leluconku sendiri daripada pada kenyamananmu.', 'If a tease does not feel good, tell me. I do not want to care more about my own joke than your comfort.');
p('Tetap kamu.', 'Still you.', 'Aku nggak sedang menunggu versi yang selalu rapi. Aku sedang mengenal orang yang nyata. Yang namanya Aira, dan panggilannya bisa sangat panjang.', 'I am not waiting for a permanently tidy version. I am getting to know a real person. Her name is Aira, and her nicknames can be very long.', 'quote');

// 77-86: little appreciations and space to breathe.
p('Hal kecil juga boleh disimpan.', 'Little things can be kept too.', 'Satu panggilan. Satu angka di jam. Nama aplikasi yang tadinya biasa. Aku suka bahwa hal-hal ini sekarang punya hubungan dengan kamu.', 'A nickname. A time on a clock. An app name that used to be ordinary. I like that these things now connect to you.');
p('Bebyycu, satu huruf lebih pendek.', 'Bebyycu, one letter shorter.', 'Versi kamu untukku memang begitu. Aku memperhatikannya. Bukan untuk koreksi ejaan, cuma karena detail kecil kita menyenangkan buat disimpan.', 'That is your version for me. I noticed. Not to correct spelling, just because our little details are nice to keep.');
p('Yang biasa bukan berarti kurang.', 'Ordinary does not mean lesser.', 'Aku ingin hubungan ini boleh punya bagian yang tidak dramatis. Percakapan biasa juga boleh bernilai, tanpa harus berubah jadi kutipan.', 'I want this relationship to have undramatic parts. Ordinary conversation can matter without turning into a quote.', 'quote');
p('Aku tidak perlu terdengar keren.', 'I do not need to sound cool.', 'Kalau panggilannya Ciyanggcuu, sepertinya citra keren sudah kita lepaskan sejak awal. Nggak apa-apa. Yang penting kamu mengenali aku di kata-katanya.', 'With a name like Ciyanggcuu, I think we gave up the cool image early on. That is fine. What matters is that you recognise me in the words.');
p('Satu sudut untuk kenangan.', 'A corner for memories.', 'Ada halaman yang tidak butuh banyak penjelasan. Cukup ruang kecil untuk melihat, berhenti, lalu melanjutkan saat kamu mau.', 'Some pages do not need much explanation. Just a small space to look, pause, and continue when you want.');
p('Yang ingin kamu simpan?', 'What would you like to keep?', 'Kalau boleh memilih satu hal kecil dari kita untuk masuk buku berikutnya, apa? Aku ingin tahu apa yang menurutmu layak mendapat halaman.', 'If you could choose one little thing about us for the next book, what would it be? I want to know what you think deserves a page.', 'question');
p('Tidak semua perlu judul besar.', 'Not everything needs a big heading.', 'Pelan-pelan menjadi dekat kadang tidak punya tanggal sendiri. Tapi aku tetap menghargai prosesnya, bahkan tanpa angka untuk ditulis di bawahnya.', 'Gradually becoming close may not have a date of its own. I still value the process, even without a number to write underneath it.');
p('Kamu boleh berhenti dulu.', 'You can pause here.', 'Kalau sudah capek membaca, tutup bukunya dulu. Ini bukan ujian ketahanan menghadapi tulisan pacar. Halamannya tetap menunggu.', 'If reading feels tiring, close the book for a while. This is not an endurance test for your boyfriend\'s writing. The pages will wait.');
p('Catatan untuk diriku.', 'A note to myself.', 'Perhatian bukan cuma bisa menulis panjang. Setelah buku ini selesai pun, aku masih perlu mendengarkan. Shivam, jangan cuma pandai di halaman.', 'Care is not just being able to write a lot. Even after this book is finished, I still need to listen. Shivam, do not only be good on paper.', 'note');
p('Sebelum surat-suratnya.', 'Before the letters.', 'Berikutnya ada dua belas surat. Ada yang tenang, ada yang lucu, ada yang mungkin ingin kamu baca pelan. Ambil waktumu, Cantikkcuu.', 'Next come twelve letters. Some quiet, some funny, some you may want to read slowly. Take your time, Cantikkcuu.');

letters.forEach((letter, letterIndex) => letter.parts.forEach((part, partIndex) => {
  const page = p(letter.title.id, letter.title.en, part.id, part.en, 'letter');
  page.letter = letterIndex;
  page.part = partIndex;
}));

for (let i = 0; i < 25; i++) {
  const page = p('Dua alasan kecil lagi.', 'Two more little reasons.', reasons[i * 2].id, reasons[i * 2].en, 'reasons');
  page.reasons = [i * 2, i * 2 + 1];
  if (i === 24) page.detail = reasonsAfterword;
}

export const gameNames = [
  t('Kuis kecil tentang kita', 'Love Quiz'), t('Pasangan yang cocok', 'Memory Match'), t('Kode gambar', 'Emoji Decode'),
  t('Pilih satu, Bebyycuu', 'This or That'), t('Huruf yang berantakan', 'Word Scramble'), t('Cari hati kecilnya', 'Find the Hidden Heart'),
  t('Tebak pilihanku', 'Guess My Answer'), t('Susun jejak kita', 'Love Timeline Puzzle'), t('Tantangan terakhir', 'Final Love Challenge'),
];
gameNames.forEach((name, i) => {
  const page = p(name.id, name.en, 'Kita istirahat dari membaca dulu. Sekarang giliran kamu main.', 'Let us take a break from reading. Your turn to play.', 'game');
  page.game = i;
});
envelopes.forEach((envelope, i) => {
  const page = p(envelope.title.id, envelope.title.en, 'Ada surat di dalamnya. Buka kalau judulnya terasa pas untuk hari ini.', 'There is a note inside. Open it when the title feels right for today.', 'envelope');
  page.envelope = i;
});

// 167-174: hopes remain hopes, not invented plans.
p('Kalau nanti ketemu.', 'When we finally meet.', 'Aku berharap kita bisa ketemu langsung tahun depan. Aku ingin menulisnya sebagai harapan yang jujur, bukan jadwal yang sudah pasti.', 'I hope we can meet in person next year. I want to write that as an honest hope, not a confirmed schedule.');
p('Tahun depan versiku.', 'My version of next year.', 'Ada rasa tidak sabar yang manis saat memikirkan pertemuan itu. Tapi aku nggak mau buru-buru mengisi tanggal yang belum kita tentukan.', 'There is a sweet impatience in thinking about meeting. But I do not want to fill in a date we have not chosen.');
p('Dan 2028 versi kamu.', 'And your version, 2028.', 'Iya, Aira kadang menyebut 2028. Kalender kita mungkin butuh duduk bareng dulu. Aku boleh menghela napas sedikit sambil tetap menghargai waktumu.', 'Yes, Aira sometimes mentions 2028. Our calendars may need to sit down together first. I can sigh a little while still respecting your timing.', 'note');
p('Bukan adegan yang harus dipenuhi.', 'Not a scene to perform.', 'Saat ketemu nanti, kamu nggak perlu menjadi bayangan yang sudah kususun. Aku ingin kenal orangnya, termasuk kalau ada canggung yang sangat manusiawi.', 'When we meet, you do not have to become an image I have arranged. I want to know the person, including any very human awkwardness.');
p('Yang perlu dibicarakan.', 'Things to talk about.', 'Waktu, keadaan, kenyamanan dua orang. Aku ingin harapan ini punya tempat untuk kenyataan juga. Sesuatu yang manis boleh tetap masuk akal.', 'Timing, circumstances, and both people\'s comfort. I want this hope to leave room for reality too. Something sweet can still be sensible.');
p('Satu hal yang ingin kamu lakukan?', 'One thing you would like to do?', 'Tanpa menjadikannya janji, apa satu hal sederhana yang ingin kamu lakukan kalau kita bertemu? Tulis sebagai harapan saja.', 'Without making it a promise, what is one simple thing you would like to do if we meet? Write it as a hope.', 'question');
p('Belum terjadi, tetap boleh berharap.', 'Not happened yet, still worth hoping for.', 'Aku menyisakan ruang untuk kenangan yang belum ada. Rasanya menyenangkan tahu masih ada hal tentang kita yang nanti baru bisa diceritakan setelah dijalani.', 'I am leaving room for memories that do not exist yet. It feels good to know there are parts of us we can only tell after actually living them.');
p('Sekarang bukan ruang tunggu.', 'The present is not a waiting room.', 'Kita nggak perlu meremehkan yang lewat layar sambil berharap bisa bertemu. Empat bulan ini tetap bagian yang nyata dari kita.', 'We do not need to dismiss what happens through a screen while hoping to meet. These four months are still a real part of us.', 'quote');

// 175-180: the relationship timeline contains only supplied facts.
p('Jejak kecil kita.', 'Our little timeline.', 'Kalau cerita kita dibuat singkat, jejaknya kurang lebih begini. Ada yang sudah kita jalani, ada satu harapan yang masih menunggu waktunya.', 'If our story were told briefly, its little trail would look like this. Some things we have lived, and one hope is still waiting for its time.', 'timeline');
p('Awal yang berurutan.', 'A beginning in order.', 'Pertama, Litmatch. Lalu WhatsApp di malam yang sama. Hubungan kita dimulai pada 6 Juli 2026, pukul 10:29 malam. Tiga bagian awal yang tidak ingin kutukar-tukar.', 'First, Litmatch. Then WhatsApp that same night. Our relationship began on 6 July 2026 at 10:29 PM. Three parts of the beginning I want to keep in order.');
p('Sesudah hari-hari awal.', 'After the early days.', 'Sekitar sepuluh hari pertama tidak selalu mudah. Sesudahnya, kita berangsur saling memahami dan lebih dekat. Aku suka bahwa awal yang berisik itu bukan satu-satunya hal yang bisa kita ceritakan.', 'The first ten days or so were not always easy. Afterwards, we gradually understood each other and grew closer. I like that the noisy beginning is not the only thing we have to tell.');
p('Ada yang tidak bertanggal.', 'Some moments have no date here.', 'Panggilan pertama dan momen cium itu tetap punya tempat, meskipun buku ini tidak memaksakan tanggal untuk keduanya. Nilainya tidak berkurang karena itu.', 'Our first call and that kiss moment still have a place, even though this book does not force dates onto them. That does not make them matter less.');
p('Hari ini kita rayakan.', 'Today, we celebrate.', 'Empat bulan. Aku ingin memberi ruang untuk melihat ke belakang dengan jujur dan ke depan tanpa terburu-buru. Juga sedikit ruang buat candaan, tentu.', 'Four months. I want space to look back honestly and look ahead without rushing. Also a little space for jokes, obviously.');
p('Bagian berikutnya belum ditulis.', 'The next part is unwritten.', 'Harapan ketemu tahun depan masih ada. Angka 2028 dari kamu juga tidak kuhapus. Kita bicarakan, bukan kita paksa jadi satu adegan indah.', 'The hope of meeting next year is still here. I have not erased your 2028 either. We can discuss it rather than force it into a beautiful scene.');

// 181-190: varied, personal notes and questions.
p('Ada catatan di pinggir.', 'A note in the margin.', 'Kalau tadi menemukan hati kecil di beberapa halaman, itu memang sengaja. Ada pesan yang tidak perlu tampil paling besar untuk terasa dekat.', 'If you found little hearts on some pages, that was deliberate. Some notes do not need to be the largest thing to feel personal.', 'note');
p('Pengakuan penulis.', 'The writer admits.', 'Aku ingin buku ini terasa buatan tangan, walaupun kamu membukanya lewat layar. Jadi kalau ada bagian yang agak konyol, anggap itu sidik jari Shivam.', 'I want this to feel handmade even though you open it on a screen. So if a part is a little silly, consider it Shivam\'s fingerprint.', 'note');
p('Untuk dibaca tanpa terburu.', 'For reading without rushing.', 'Tidak ada hadiah tambahan kalau kamu selesai paling cepat. Boleh tinggal di satu foto, satu kalimat, atau satu permainan dulu. Ini bukan perlombaan.', 'There is no extra prize for finishing fastest. You can stay with one photo, one sentence, or one game. This is not a race.');
p('Pertanyaan yang agak penting.', 'A slightly important question.', 'Dari semua panggilan kita, mana yang menurutmu paling tidak masuk akal? Jawaban yang merugikan penulis tetap diterima.', 'Of all our nicknames, which do you think makes the least sense? Answers that embarrass the writer are still accepted.', 'question');
p('Kalau aku sedang sok puitis.', 'If I get too poetic.', 'Tolong ingat bahwa orang yang menulis kalimat lembut ini juga orang yang balas Lesbian. Jangan biarkan jenis huruf cantik mengaburkan fakta.', 'Please remember that the person writing these gentle sentences is also the person who replies Lesbian. Do not let a pretty font obscure the facts.', 'note');
p('Halaman yang tidak meminta apa-apa.', 'A page that asks for nothing.', 'Kamu boleh sekadar melihat. Nggak perlu memberi reaksi, membuat kesimpulan, atau menjelaskan perasaan. Kadang hadiah boleh cuma menemani sebentar.', 'You can simply look. No reaction, conclusion, or explanation of feelings needed. Sometimes a gift can just keep you company for a little while.');
p('Satu kalimat buat nanti.', 'A sentence for later.', 'Kalau ada yang ingin dikatakan tapi belum menemukan kata, kamu boleh menulis versi berantakannya dulu. Aku juga tidak selalu rapi.', 'If there is something you want to say but cannot find the words, write the messy version first. I am not always tidy either.', 'question');
p('Catatan yang kuselipkan.', 'A note I tucked in.', 'Aku suka membuat sesuatu yang tujuannya jelas: untuk kamu. Tanpa harus disukai semua orang. Tanpa harus terlihat seperti hadiah milik orang lain.', 'I like making something with a clear purpose: for you. It does not have to please everyone or look like someone else\'s gift.', 'note');
p('Boleh baca ulang yang lucu.', 'You can reread the funny parts.', 'Kalau suatu saat cuma mau buka bagian panggilan atau permainan, boleh. Kamu nggak berutang pembacaan serius setiap kali membuka buku ini.', 'If you only want the nicknames or games one day, that is fine. You do not owe this book a serious reading every time.');
p('Yang ingin kamu tambahkan.', 'What you would add.', 'Kalau ada satu halaman yang ingin kamu tulis sendiri untuk kita, judulnya apa? Aku beri ruang di sini. Tidak akan kuedit jadi lebih romantis.', 'If you could write one page for us, what would its title be? There is room here. I will not edit it to make it more romantic.', 'question');

// 191-194: the reader's voice, saved on this device only.
p('Sekarang giliran kamu.', 'Now it is your turn.', 'Kalau ingin meninggalkan sesuatu, tulis di sini. Pesannya disimpan hanya di perangkat ini, bukan dikirim diam-diam ke mana-mana. Kamu bisa unduh untuk membagikannya padaku.', 'If you want to leave something, write it here. Notes stay on this device; they are not secretly sent anywhere. You can download them to share with me.', 'guestbook');
p('Nggak perlu jawaban sempurna.', 'No perfect answer needed.', 'Boleh komentar pendek, boleh protes soal godaan, boleh cuma tulis panggilan aneh kita. Aku lebih suka suaramu yang asli daripada balasan yang terasa wajib.', 'A short comment, a complaint about the teasing, or just our strange nicknames. I would rather hear your real voice than a reply that feels compulsory.');
p('Satu hal dari empat bulan ini.', 'One thing from these four months.', 'Apa yang ingin kamu bawa ke bulan berikutnya, dan apa yang ingin lebih kita pahami? Tulis kalau mau. Kita tidak harus langsung menyelesaikannya di halaman ini.', 'What would you like to carry into the next month, and what would you like us to understand better? Write if you want. We do not have to solve it on this page.', 'question');
p('Terima kasih sudah ikut menulis.', 'Thank you for adding your voice.', 'Bahkan kalau kamu tidak mengisi satu kolom pun, bukunya tetap untukmu. Pilihan untuk bercerita juga berarti boleh memilih diam dulu.', 'Even if you do not fill in a single box, the book is still yours. Having a choice to speak also means being allowed to stay quiet for now.');

// 195-200: one final photograph and the required surprise.
p('Hampir sampai, Bebyycuu.', 'Almost there, Bebyycuu.', 'Kalau kamu sampai di sini dengan membaca satu-satu, aku terharu. Kalau lewat daftar isi, aku juga paham. Ini memang buku yang cukup ambisius untuk pembaca yang bisa malas.', 'If you got here reading every page, I am touched. If you used the contents, I understand too. This is an ambitious book for a reader who can be lazy.', 'note');
p('Satu sudut terakhir.', 'One last little corner.', 'Sebelum penutup, aku ingin ada tempat untuk berhenti sebentar. Tidak semua akhir halaman harus diburu. Yang ini khusus untuk kamu.', 'Before the closing, I wanted somewhere to pause. Not every page ending needs to be rushed. This one is just for you.');
p('Selamat empat bulan.', 'Happy four months.', 'Untuk Litmatch yang jadi awal. Untuk WhatsApp di malam yang sama. Untuk 10:29 yang sekarang punya arti. Dan untuk kamu yang membuat semua detail itu layak disimpan.', 'For Litmatch, where we began. For WhatsApp that same night. For 10:29, which now means something. And for you, who makes all those details worth keeping.', 'quote');
p('Masih ada satu hal.', 'One more thing.', 'Aku sudah mencoba menutupnya dengan anggun. Tapi sepertinya kamu kenal penulisnya terlalu baik untuk percaya bahwa semuanya akan berakhir begitu saja.', 'I tried to end this elegantly. But I think you know the writer too well to believe it will finish like that.', 'note');
p('Foto terakhir, bukan cerita terakhir.', 'The last photo, not the last chapter.', 'Ruang yang ini untuk satu foto penutup. Bukan untuk mengatakan kita sudah selesai, cuma karena dua ratus halaman ternyata tetap punya ujung.', 'This space is for a final photo. Not to say we are finished, just because even two hundred pages eventually have an edge.');
p('Ternyata penutupnya begini.', 'So this is how it ends.', 'LESBICUUUU ❤️', 'LESBICUUUU ❤️', 'final');

